let roadEventsEnabled=false,lastRoadEventLoad=null,roadEventRequest=null,userPosition=null,userLocationMarker=null,userAccuracyCircle=null,userWatchId=null,dailyNavigationActive=false,dailyNavigationMeters=0,lastDailyPosition=null;
