function ensurePlateLookup(){if($('lookupPlateBtn'))return;const input=$('vPlate'),label=input.closest('label'),box=document.createElement('div');box.className='plate-lookup';input.insertAdjacentElement('beforebegin',box);box.append(input);box.insertAdjacentHTML('beforeend','<button id="lookupPlateBtn" type="button">Consultar</button>');label.insertAdjacentHTML('beforeend','<small id="plateLookupStatus" class="plate-lookup-status">Informe a placa para preencher os dados do veículo.</small>');input.addEventListener('input',()=>{input.value=input.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7)});$('lookupPlateBtn').onclick=lookupPlate}
async function lookupPlate(){const plate=$('vPlate').value.toUpperCase().replace(/[^A-Z0-9]/g,''),button=$('lookupPlateBtn'),status=$('plateLookupStatus');if(!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(plate)){status.textContent='Informe uma placa válida no formato ABC1D23.';return}button.disabled=true;button.textContent='Consultando…';status.textContent='Buscando dados públicos do veículo…';try{const response=await fetch(`/api/vehicles/lookup?plate=${encodeURIComponent(plate)}`),data=await response.json();if(!response.ok){const error=new Error(data.error);error.code=data.code;throw error}const item=data.vehicle,fields={vPlate:item.plate,vBrand:item.brand,vModel:item.model,vYear:item.year,vVersion:item.version,vEngine:item.engine,vTransmission:item.transmission,vFuel:item.fuel};Object.entries(fields).forEach(([id,value])=>{if(value&&$(id))$(id).value=value});const fipe=item.fipe?.value?` · FIPE ${item.fipe.value} (${item.fipe.referenceMonth||'referência atual'})`:'';$('pbeSource').textContent=`Dados públicos consultados pela placa · ${item.source||item.provider}${fipe}`;status.textContent=`Encontrado: ${item.brand} ${item.model}${item.year?` · ${item.year}`:''}. Confira os dados antes de salvar; a consulta não prova propriedade.`;toast(item.fipe?'Dados do veículo e referência FIPE preenchidos.':'Dados do veículo preenchidos pela placa.')}catch(error){const unavailable=['PROVIDER_UNAVAILABLE','PROVIDER_TIMEOUT','PROVIDER_RATE_LIMIT','PROVIDER_AUTH_ERROR'].includes(error.code);status.textContent=unavailable?`${error.message} Tente novamente ou preencha manualmente.`:error.message;toast(status.textContent)}finally{button.disabled=false;button.textContent='Consultar'}}
function renderVehicleSummary(){$('vehicleSummary').classList.remove('empty');$('vehicleSummary').innerHTML=`<b>${escapeHtml(vehicle.nickname)}</b> · ${escapeHtml(vehicle.plate||'sem placa')}<br>${escapeHtml(vehicle.brand)} ${escapeHtml(vehicle.model)} ${escapeHtml(vehicle.version)} · ${escapeHtml(vehicle.fuel)}`;updateConsumption()}
function renderFuelPrice(){const input=$('fuelPriceInput'),source=$('fuelPriceSource');if(!input||!source)return;input.value=fuelPricePreference?.pricePerLiter??'';source.textContent=fuelPricePreference?`Fonte: ${fuelPricePreference.source==='user-provided'?'informado pelo usuário':fuelPricePreference.source}${fuelPricePreference.region?` · ${fuelPricePreference.region}`:''}`:'Fonte: não informada';updateConsumption()}
