async function saveFuelPrice(){if(!vehicle?.fuel)return toast('Selecione um veículo com combustível informado.');const pricePerLiter=Number($('fuelPriceInput').value);if(!(pricePerLiter>0&&pricePerLiter<=100))return toast('Informe um preço válido por litro.');const response=await fetch('/api/fuel-price',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({fuelType:vehicle.fuel,pricePerLiter})}),data=await response.json();if(!response.ok)return toast(data.error);fuelPricePreference=data.preference;renderFuelPrice();toast('Preço salvo separadamente do veículo.')}
function vehiclePayload(){return{nickname:$('vNickname').value,type:$('vType')?.value||'car',plate:$('vPlate').value.toUpperCase(),brand:$('vBrand').value,model:$('vModel').value,year:Number($('vYear').value),version:$('vVersion').value,engine:$('vEngine').value,transmission:$('vTransmission').value,fuel:$('vFuel').value,city:Number($('vCity').value),road:Number($('vRoad').value),tank:Number($('vTank').value),dataSource:$('pbeSource').textContent||'manual',sourceDate:new Date().toISOString().slice(0,10)}}
async function saveVehicle(){const payload=vehiclePayload(),url=editingVehicleId?`/api/vehicles/${editingVehicleId}`:'/api/vehicles',method=editingVehicleId?'PUT':'POST';const res=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await res.json();if(!res.ok)throw new Error(data.error);vehicle=data.vehicle;editingVehicleId=null;$('vehicleDialog').close();await loadVehicles();toast('Perfil do veículo salvo.')}
