function renderVehicleCards(){const grid=$('vehiclesGrid');if(!grid)return;grid.innerHTML=savedVehicles.length?savedVehicles.map(v=>`<article class="vehicle-card ${v.selected?'selected':''}"><div class="vehicle-card-head"><span class="vehicle-type">${v.type==='motorcycle'?'MOTO':'CARRO'}</span>${v.selected?'<span class="badge online">Selecionado</span>':''}</div><h3>${escapeHtml(v.nickname)}</h3><p>${escapeHtml(v.brand)} ${escapeHtml(v.model)} ${escapeHtml(v.version)}</p><dl><div><dt>Ano</dt><dd>${v.year||'—'}</dd></div><div><dt>Placa</dt><dd>${escapeHtml(v.plate||'Não informada')}</dd></div><div><dt>Rastreador</dt><dd>Celular demo</dd></div><div><dt>Fonte</dt><dd>${escapeHtml(v.dataSource)}</dd></div></dl><div class="vehicle-actions">${v.selected?'':`<button data-select="${v.id}">Selecionar</button>`}<button class="secondary" data-edit="${v.id}">Editar</button><button class="danger" data-delete="${v.id}">Excluir</button></div></article>`).join(''):'<div class="empty-garage"><h3>Nenhum veículo cadastrado</h3><p>Adicione seu primeiro veículo para começar uma viagem.</p></div>';grid.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectVehicle(Number(b.dataset.select)));grid.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openVehicleForm(savedVehicles.find(v=>v.id===Number(b.dataset.edit))));grid.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteVehicle(Number(b.dataset.delete)))}
