async function deletePrivacyAccount(){const password=$('privacyPassword').value,confirmation=$('deleteConfirmation').value;if(!password)return toast('Informe sua senha atual.');if(confirmation!=='EXCLUIR MINHA CONTA')return toast('Digite a frase de confirmação exatamente como exibida.');if(!confirm('Esta ação é permanente. Deseja realmente excluir a conta e todos os dados associados?'))return;const button=$('deleteAccountBtn');button.disabled=true;try{const csrfResponse=await fetch('/api/auth/csrf'),csrfData=await csrfResponse.json();if(!csrfResponse.ok)throw new Error(csrfData.error||'Não foi possível validar esta operação.');const response=await fetch('/api/privacy/account',{method:'DELETE',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfData.token},body:JSON.stringify({password,confirmation})});if(!response.ok){const data=await response.json();throw new Error(data.error||'Não foi possível excluir a conta.')}location.replace('/login.html')}catch(error){toast(error.message);button.disabled=false}}
const achievementNames={PRIMEIRA_VIAGEM:'Primeira viagem',EXPLORADOR_RESPONSAVEL:'Explorador responsável',CONEXAO_CONSISTENTE:'Conexão consistente',ROTINA_PROTEGIDA:'Rotina protegida',GUARDIAO_DA_AREA:'Guardião da área'};
async function loadGamification(){const [mine,ranking]=await Promise.all([fetch('/api/gamification/me').then(r=>r.json()),fetch('/api/gamification/ranking').then(r=>r.json())]);$('safeScore').textContent=mine.progress.score;$('rankingEnabled').checked=mine.profile.enabled;$('rankingName').value=mine.profile.displayName||'';const labels={completedTrips:'Viagens concluídas',continuity:'Continuidade',scheduleCompliance:'Respeito aos horários',geofenceCompliance:'Proteção de área',dataQuality:'Qualidade do GPS'};$('scoreBreakdown').innerHTML=Object.entries(mine.progress.breakdown).map(([key,value])=>`<div><span>${labels[key]}</span><b>+${value}</b></div>`).join('');$('achievementList').innerHTML=mine.progress.achievements.map(item=>`<span>◆ ${achievementNames[item]||item}</span>`).join('')||'<small>Finalize uma viagem para liberar conquistas.</small>';$('rankingList').innerHTML=ranking.ranking.length?ranking.ranking.map(item=>`<div><b>${item.position}º</b><span>${escapeHtml(item.displayName)}</span><strong>${item.score}</strong></div>`).join(''):'<p class="muted-copy">Ainda não há participantes no ranking.</p>'}
