async function createSession(){if(!vehicle){openVehicleForm();return toast('Configure o veículo antes de criar a sessão.')}try{const res=await fetch('/api/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicleId:vehicle.id})}),d=await res.json();if(!res.ok)throw new Error(d.error);sessionId=d.id;mobileUrl=d.mobileUrl;$('qrImage').src=d.qrCode;$('sessionCode').textContent=d.pairingCode;$('sessionCode').parentElement.firstChild.textContent='Código ';let instructions=$('manualMobileInstructions');if(!instructions){instructions=document.createElement('small');instructions.id='manualMobileInstructions';$('sessionCode').parentElement.insertAdjacentElement('afterend',instructions)}instructions.textContent=`No celular, abra ${d.lanMobilePageUrl||'/mobile.html'} e digite este código (válido por ${d.pairingExpiresInMinutes} min).`;$('sessionEmpty').classList.add('hidden');$('sessionActive').classList.remove('hidden');$('clearBtn').disabled=false;$('closeBtn').disabled=false;socket.emit('session:join',{sessionId,role:'dashboard'});toast('Sessão criada. Use o código no celular ou o QR Code.')}catch(e){toast(e.message||'Não foi possível criar a sessão.')}}
async function startTrip(){if(!plannedRoutes.length)return toast('Calcule uma rota antes de iniciar.');if(!sessionId)return toast('Crie uma sessão de rastreamento antes de iniciar.');if(!tripStart){tripStart=Date.now();tripEnd=null;try{const response=await fetch('/api/trips',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({trackingSessionId:sessionId,vehicleId:vehicle.id,plannedRoute:plannedRoutes[selectedRoute],startedAt:tripStart})}),data=await response.json();if(!response.ok)throw new Error(data.error);tripId=data.trip.id;$('tripStarted').textContent=new Date(tripStart).toLocaleString('pt-BR');$('startTripBtn').textContent='Finalizar viagem';navigation.start();addEvent('Viagem iniciada',`${vehicle.nickname} · rota planejada preservada`);socket.emit('trip:update',{startedAt:tripStart,route:plannedRoutes[selectedRoute],vehicle});checkSchedule()}catch(error){tripStart=null;toast(error.message)}}else{tripEnd=Date.now();if(tripId){const response=await fetch(`/api/trips/${tripId}/finish`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({endedAt:tripEnd})});if(!response.ok)return toast('Não foi possível finalizar a viagem.')}navigation.stop();$('tripEnded').textContent=new Date(tripEnd).toLocaleString('pt-BR');$('startTripBtn').textContent='Viagem finalizada';$('startTripBtn').disabled=true;addEvent('Viagem finalizada',`Distância total estimada: ${formatDistance(confirmedMeters+rebuiltMeters)}`);updateTimeline()}}
async function loadTripHistory(){const response=await fetch('/api/trips'),data=await response.json();historyTrip=null;$('replayTripBtn').disabled=true;if(!response.ok||!data.trips.length)return;const latest=await fetch(`/api/trips/${data.trips[0].id}`).then(r=>r.json()).then(value=>value.trip);historyTrip=latest;$('replayTripBtn').disabled=!Array.isArray(latest.actualTrack)||latest.actualTrack.length<2;$('tripStarted').textContent=new Date(latest.startedAt).toLocaleString('pt-BR');$('tripEnded').textContent=latest.endedAt?new Date(latest.endedAt).toLocaleString('pt-BR'):'Em andamento';$('tripDuration').textContent=formatDuration(latest.comparison.actualDurationSeconds);$('movingTime').textContent=formatDuration(latest.comparison.movingSeconds);$('stoppedTime').textContent=formatDuration(latest.comparison.stoppedSeconds);const comparison=`Planejado: ${formatDistance(latest.comparison.plannedDistanceMeters)} · realizado: ${formatDistance(latest.comparison.actualDistanceMeters)} · diferença: ${formatDistance(Math.abs(latest.comparison.distanceDifferenceMeters))}`;$('eventTimeline').innerHTML=`<div class="event-item"><b>Comparação da última viagem</b><small>${comparison}</small></div>`+latest.interruptions.map(item=>`<div class="event-item alert"><b>Interrupção de conexão</b><small>${formatDuration((item.duration||0)/1000)} · ${escapeHtml(item.classification)}</small></div>`).join('')}
