function renderPosition(p){if(replayTimer||!$('replayBadge').classList.contains('hidden'))stopTripReplay();const previous=positions.at(-1),step=previous?haversine(previous,p):0;if(previous&&step<2000){confirmedMeters+=step;const dt=Math.max(0,p.timestamp-previous.timestamp);if((p.speed||0)>0.8)movingMs+=dt;else stoppedMs+=dt;L.polyline([[previous.latitude,previous.longitude],[p.latitude,p.longitude]],{color:p.capturedOffline?'#ffd33d':'#39d98a',weight:4}).addTo(layers.confirmed)}positions.push(p);const ll=[p.latitude,p.longitude];if(!vehicleMarker)vehicleMarker=L.marker(ll,{icon}).addTo(map);navigation.interpolator.move(vehicleMarker,previous,p);if(!accuracyCircle)accuracyCircle=L.circle(ll,{radius:p.accuracy,color:'#3c91e6',fillOpacity:.1}).addTo(map);else accuracyCircle.setLatLng(ll).setRadius(p.accuracy);$('latitude').textContent=p.latitude.toFixed(6);$('longitude').textContent=p.longitude.toFixed(6);$('accuracy').textContent=`${br(p.accuracy)} m`;$('accuracyClass').textContent=accuracyLabel(p.accuracy);const kmh=Math.max(0,p.speed||0)*3.6;navigation.update(p,kmh,confirmedMeters+rebuiltMeters);loadRoadEvents(p);$('speed').textContent=br(kmh);$('heading').textContent=p.heading==null?'Indisponível':`${br(p.heading,0)}°`;$('dataSource').className='badge online';$('dataSource').textContent=p.source==='simulation'?'Dados simulados':'GPS autorizado';speeds.push(kmh);lastTimestamp=p.timestamp;updateStats();checkSchedule();if(pendingGap&&!p.capturedOffline){reconstructGap(pendingGap,p);pendingGap=null}}
function updateStats(){const total=confirmedMeters+rebuiltMeters;$('confirmedDistance').textContent=formatDistance(confirmedMeters);$('rebuiltDistance').textContent=formatDistance(rebuiltMeters);$('totalDistance').textContent=formatDistance(total);$('confirmedDuration').textContent=formatDuration((movingMs+stoppedMs)/1000);$('offlineTime').textContent=formatDuration(offlineMs/1000);const planned=plannedRoutes[selectedRoute]?.distance;$('routeDelta').textContent=planned?`${br((total-planned)/1000,2)} km`:'—';updateConsumption();updateTimeline()}
function updateTimeline(){const end=tripEnd||lastTimestamp||Date.now(),duration=tripStart?end-tripStart:0;$('tripDuration').textContent=formatDuration(duration/1000);$('movingTime').textContent=formatDuration(movingMs/1000);$('stoppedTime').textContent=formatDuration(stoppedMs/1000);const avg=speeds.length?speeds.reduce((a,b)=>a+b,0)/speeds.length:0,max=Math.max(0,...speeds);$('speedStats').textContent=`${br(avg)} / ${br(max)} km/h`;renderTimelineEvents()}
function updateConsumption(){if(!vehicle)return;const distanceMeters=plannedRoutes[selectedRoute]?.distance||confirmedMeters+rebuiltMeters,urbanShare=.55,totalKm=distanceMeters/1000,urbanKm=totalKm*urbanShare,roadKm=totalKm-urbanKm,urbanLiters=urbanKm/vehicle.city,roadLiters=roadKm/vehicle.road,idleLiters=stoppedMs/3600000*.8,base=urbanLiters+roadLiters+idleLiters,min=base*.92,max=base*1.18,price=fuelPricePreference?.pricePerLiter,pctMin=vehicle.tank?min/vehicle.tank*100:0,pctMax=vehicle.tank?max/vehicle.tank*100:0;$('fuelMin').textContent=br(min,2);$('fuelMax').textContent=br(max,2);$('fuelCostLine').textContent=price?`R$ ${br(min*price,2)}–${br(max*price,2)} · preço ${fuelPricePreference.source==='user-provided'?'informado':fuelPricePreference.source}`:'Custo indisponível sem preço informado';$('tankUse').style.width=`${Math.min(100,pctMax)}%`;$('tankText').textContent=`≈ ${br(pctMin)}% – ${br(pctMax)}% do tanque`;let details=$('fuelBreakdown');if(!details){details=document.createElement('dl');details.id='fuelBreakdown';details.className='fuel-breakdown';document.querySelector('.consumption .range').insertAdjacentElement('afterend',details)}details.innerHTML=`<div><dt>Consumo urbano</dt><dd>${br(vehicle.city)} km/L</dd></div><div><dt>Consumo rodoviário</dt><dd>${br(vehicle.road)} km/L</dd></div><div><dt>Distância urbana estimada</dt><dd>${br(urbanKm,2)} km</dd></div><div><dt>Distância rodoviária estimada</dt><dd>${br(roadKm,2)} km</dd></div>`}
async function reconstructGap(gap,after){
 offlineMs+=gap.duration||0;
 const lostLabel=gap.lostAt?new Date(gap.lostAt).toLocaleTimeString('pt-BR'):'horário desconhecido',backLabel=new Date(gap.reconnectedAt||Date.now()).toLocaleTimeString('pt-BR');
 if(gap.pointCount>=3){$('confidence').textContent='Confirmado por GPS local';addEvent('Conexão recuperada',`Perda ${lostLabel}, retorno ${backLabel}, ${formatDuration((gap.duration||0)/1000)}. ${gap.pointCount} pontos GPS confirmados.`);updateStats();return}
 const before=positions.filter(p=>p.timestamp<(gap.lostAt||0)).at(-1);if(!before){$('confidence').textContent='Não foi possível reconstruir';return}
 try{
  if(!tripId||!after)throw new Error();const res=await fetch(`/api/trips/${tripId}/reconstruct`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({before,after,lostAt:gap.lostAt,reconnectedAt:gap.reconnectedAt,duration:gap.duration,vehicleType:vehicle?.type})}),data=await res.json();if(!res.ok)throw new Error(data.error);const candidates=[data.probableRoute,...data.alternatives],best=data.probableRoute,labels={RECONSTRUCTED_HIGH:'alta',RECONSTRUCTED_MEDIUM:'média',RECONSTRUCTED_LOW:'baixa',UNRECONSTRUCTABLE:'insuficiente'};candidates.forEach((route,index)=>L.polyline(route.geometry,{color:index?'#8997a2':'#f28b32',weight:index?3:5,dashArray:index?'5 10':'9 8',opacity:.85}).addTo(index?layers.alternatives:layers.rebuilt));rebuiltMeters+=best.distanceMeters;$('confidence').textContent=`Rota provável · ${best.confidence}% · confiança ${labels[best.classification]}`;addEvent('Trecho reconstruído — rota provável',`Perda ${lostLabel}, retorno ${backLabel}. ${candidates.length} alternativa(s), confiança ${best.confidence}%. Resultado estimado, não confirmado.`,best.confidence<50);updateStats();
 }catch{$('confidence').textContent='Não foi possível reconstruir';addEvent('Lacuna sem reconstrução',`Perda ${lostLabel}, retorno ${backLabel}; evidência insuficiente.`,true)}
}
function startSimulation(){if(!sessionId)return toast('Crie uma sessão primeiro.');if(!plannedRoutes.length)return toast('Calcule uma rota antes de simular.');if(simulationTimer){clearInterval(simulationTimer);simulationTimer=null;$('simulateBtn').textContent='Simular percurso';return}if(!tripStart)startTrip();const geometry=plannedRoutes[selectedRoute].geometry;$('simulateBtn').textContent='Parar simulação';simulationTimer=setInterval(()=>{const current=geometry[simIndex%geometry.length],next=geometry[(simIndex+1)%geometry.length]||current,speed=10+Math.random()*7,heading=(Math.atan2(next[1]-current[1],next[0]-current[0])*180/Math.PI+360)%360;socket.emit('position:update',{deviceId:'dashboard-simulation',latitude:current[0],longitude:current[1],accuracy:7+Math.random()*5,speed,heading,altitude:null,timestamp:Date.now(),source:'simulation',sequence:++simulationSequence});simIndex++;if(simIndex>=geometry.length){clearInterval(simulationTimer);simulationTimer=null;$('simulateBtn').textContent='Simular percurso'}} ,700)}
function ensureSimulationControls(){if($('simulationScenarios'))return;const box=document.createElement('div');box.id='simulationScenarios';box.className='simulation-scenarios';box.innerHTML='<button id="simulateOfflineBtn" class="secondary">Testar offline</button><button id="simulateGeofenceBtn" class="secondary">Testar saída</button><button id="simulateScheduleBtn" class="secondary">Testar horário</button>';const side=document.querySelector('.map-side-panel');side?side.append(box):document.querySelector('.map-legend').insertAdjacentElement('afterend',box);$('simulateOfflineBtn').onclick=simulateOfflineScenario;$('simulateGeofenceBtn').onclick=simulateGeofenceExit;$('simulateScheduleBtn').onclick=simulateOutsideSchedule}
async function simulateOfflineScenario(){if(!sessionId||!plannedRoutes.length)return toast('Crie a sessão e calcule uma rota.');const geometry=plannedRoutes[selectedRoute].geometry,step=Math.max(1,Math.floor(geometry.length/5)),now=Date.now(),points=Array.from({length:5},(_,index)=>{const point=geometry[Math.min(geometry.length-1,index*step)];return{latitude:point[0],longitude:point[1],accuracy:10,speed:10,heading:0,timestamp:now+index*15000,source:'simulation',sequence:now*1000+index}}),response=await fetch('/api/simulations/offline',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId,points,lostAt:now,reconnectedAt:now+60000})}),data=await response.json();toast(response.ok?`${data.received} pontos de queda simulada sincronizados.`:data.error)}
async function simulateGeofenceExit(){if(!sessionId||!vehicle?.id)return toast('Crie a sessão e selecione um veículo.');const response=await fetch(`/api/vehicles/${vehicle.id}/geofences`),data=await response.json(),fence=data.geofences?.[0];if(!fence)return toast('Crie uma área de cobertura primeiro.');const latitude=fence.centerLat+(fence.radiusMeters*2.2/111320),send=()=>socket.emit('position:update',{deviceId:'dashboard-simulation',latitude,longitude:fence.centerLng,accuracy:6,speed:8,heading:0,timestamp:Date.now(),source:'simulation',sequence:++simulationSequence});send();setTimeout(send,350);toast('Duas leituras externas enviadas para confirmar a saída.')}
async function simulateOutsideSchedule(){if(!sessionId||!vehicle?.id)return toast('Crie uma sessão e selecione um veículo.');const now=new Date(),anotherDay=(now.getDay()+1)%7;await fetch(`/api/vehicles/${vehicle.id}/schedule`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:true,days:[anotherDay],from:'07:00',to:'19:00',timezone:'America/Sao_Paulo'})});const point=positions.at(-1)||origin||{latitude:-19.47,longitude:-42.54};socket.emit('position:update',{deviceId:'dashboard-simulation',latitude:point.latitude,longitude:point.longitude,accuracy:8,speed:8,heading:0,timestamp:Date.now(),source:'simulation',sequence:++simulationSequence});toast('Movimentação fora do dia autorizado enviada para validar o alerta.')}
function clearHistory(){positions=[];confirmedMeters=rebuiltMeters=movingMs=stoppedMs=offlineMs=0;speeds=[];layers.confirmed.clearLayers();layers.rebuilt.clearLayers();if(vehicleMarker){map.removeLayer(vehicleMarker);vehicleMarker=null}if(accuracyCircle){map.removeLayer(accuracyCircle);accuracyCircle=null}socket.emit('history:clear');updateStats();toast('Histórico apagado.')}
function closeSession(){if(!sessionId)return;socket.emit('session:close');sessionId=null;if(simulationTimer)clearInterval(simulationTimer);$('sessionActive').classList.add('hidden');$('sessionEmpty').classList.remove('hidden');$('clearBtn').disabled=$('closeBtn').disabled=true;toast('Sessão encerrada.')}
document.querySelectorAll('.nav-pill').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-pill').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(`${b.dataset.view}View`).classList.add('active');if(b.dataset.view==='tracking')setTimeout(()=>map.invalidateSize(),50);if(b.dataset.view==='profile')loadProfile();if(b.dataset.view==='vehicles')loadVehicles().then(loadGeofences);if(b.dataset.view==='gamification')loadGamification();if(b.dataset.view==='timeline'){loadTripHistory();loadSchedule()}});
