$('originMapBtn').onclick=()=>{pickMode='origin';$('mapPickHint').classList.remove('hidden')};$('destinationMapBtn').onclick=()=>{pickMode='destination';$('mapPickHint').classList.remove('hidden')};map.on('click',async e=>{if(!pickMode)return;let label='Local escolhido no mapa';try{const response=await fetch(`/api/reverse-geocode?lat=${e.latlng.lat}&lng=${e.latlng.lng}`),place=await response.json();if(response.ok)label=place.label}catch{}setPoint(pickMode,{latitude:e.latlng.lat,longitude:e.latlng.lng},label);pickMode=null;$('mapPickHint').classList.add('hidden')});
$('calculateBtn').onclick=calculateRoute;$('editVehicleBtn').onclick=()=>openVehicleForm(vehicle);$('newVehicleBtn').onclick=()=>openVehicleForm();$('closeVehicle').onclick=()=>{$('vehicleDialog').close();editingVehicleId=null};$('referenceModel').onchange=e=>applyModel(models.find(m=>m.id===e.target.value));$('vehicleForm').addEventListener('submit',async e=>{e.preventDefault();try{await saveVehicle()}catch(error){toast(error.message)}});$('createBtn').onclick=createSession;$('startTripBtn').onclick=startTrip;$('simulateBtn').onclick=startSimulation;$('clearBtn').onclick=clearHistory;$('closeBtn').onclick=closeSession;$('centerBtn').onclick=()=>vehicleMarker?map.setView(vehicleMarker.getLatLng(),17):plannedRoutes.length&&map.fitBounds(L.latLngBounds(plannedRoutes[selectedRoute].geometry));$('copyBtn').onclick=async()=>{await navigator.clipboard.writeText(mobileUrl);toast('Link copiado.')};$('saveSchedule').onclick=saveSchedule;$('applyFilter').onclick=()=>toast('Filtro aplicado aos dados desta demonstração.');
