socket.on('connect',()=>{$('panelStatus').className='badge online';$('panelStatus').textContent='● Painel conectado';if(sessionId)socket.emit('session:join',{sessionId,role:'dashboard'})});socket.on('disconnect',()=>{$('panelStatus').className='badge offline';$('panelStatus').textContent='● Painel offline'});socket.on('session:status',s=>{if(!$('phoneStatus'))return;$('phoneStatus').className=`badge ${s.phoneConnected?'online':'offline'}`;$('phoneStatus').textContent=s.phoneConnected?'● Celular conectado':'● Desconectado'});socket.on('position:update',renderPosition);socket.on('offline:recovered',gap=>{if(gap.pointCount>=3)reconstructGap(gap,null);else pendingGap=gap});socket.on('history:cleared',()=>{if(positions.length)clearHistory()});
socket.on('alert:new',alert=>{toast(`ALERTA: ${alert.title}`);const detail=alert.type==='OUTSIDE_ALLOWED_TIME'?`Horário configurado: ${alert.details.configured}`:`Área: ${alert.details.geofenceName||'configurada'} · distância ${formatDistance(alert.details.distanceMeters||0)}`;addEvent(alert.title,`${detail} · precisão ${br(alert.details.accuracy)} m`,alert.severity!=='info',alert.occurredAt)});
